import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import supabase from "@/lib/supabase";
import { useAuth } from "@/contexts/AuthContext";
import type { IntegrationRow } from "@/types/database";

// ── Types ─────────────────────────────────────────────────────

export type IntegrationProvider = IntegrationRow["provider"];

interface ConnectIntegrationInput {
  provider: IntegrationProvider;
  trackingId: string;
}

interface DisconnectIntegrationInput {
  provider: IntegrationProvider;
}

// ── Query keys ─────────────────────────────────────────────────

export const integrationKeys = {
  all: ["integrations"] as const,
};

// ── useIntegrations ────────────────────────────────────────────
// Fetches all integrations for the current user.

export function useIntegrations() {
  const { profile } = useAuth();
  const userId = profile?.id;

  return useQuery({
    queryKey: integrationKeys.all,
    queryFn: async (): Promise<IntegrationRow[]> => {
      if (!userId) return [];

      const { data, error } = await supabase
        .from("integrations")
        .select("*")
        .eq("user_id", userId)
        .order("connected_at", { ascending: false });

      if (error) throw new Error(error.message);
      return data as IntegrationRow[];
    },
    enabled: !!userId,
    staleTime: 1000 * 60, // 1 minute
  });
}

// ── useConnectIntegration ──────────────────────────────────────
// Upserts an integration row. Creates on first connect, updates on reconnect.

export function useConnectIntegration() {
  const { profile } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ provider, trackingId }: ConnectIntegrationInput): Promise<IntegrationRow> => {
      const userId = profile?.id;
      if (!userId) throw new Error("Not authenticated");

      const { data, error } = await supabase
        .from("integrations")
        .upsert(
          {
            user_id: userId,
            provider,
            access_token: trackingId,
            is_active: true,
          },
          { onConflict: "user_id,provider" }
        )
        .select("*")
        .single();

      if (error) throw new Error(error.message);
      return data as IntegrationRow;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: integrationKeys.all });
    },
  });
}

// ── useDisconnectIntegration ───────────────────────────────────
// Marks an integration as inactive and clears the stored token.

export function useDisconnectIntegration() {
  const { profile } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ provider }: DisconnectIntegrationInput): Promise<void> => {
      const userId = profile?.id;
      if (!userId) throw new Error("Not authenticated");

      const { error } = await supabase
        .from("integrations")
        .update({ is_active: false, access_token: null })
        .eq("user_id", userId)
        .eq("provider", provider);

      if (error) throw new Error(error.message);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: integrationKeys.all });
    },
  });
}

import { useState } from "react";
import {
  BarChart2,
  Flame,
  MousePointer2,
  Search,
  CheckCircle2,
  Circle,
  Loader2,
  type LucideIcon,
} from "lucide-react";
import { toast } from "sonner";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Skeleton } from "@/components/ui/skeleton";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { PageHeader } from "@/components/shared/PageHeader";
import { PageTransition } from "@/components/shared/PageTransition";
import {
  useIntegrations,
  useConnectIntegration,
  useDisconnectIntegration,
  type IntegrationProvider,
} from "@/hooks/use-integrations";

// ── Integration config types ───────────────────────────────────

interface IntegrationConfig {
  id: IntegrationProvider;
  name: string;
  icon: LucideIcon;
  color: string;
  bg: string;
  description: string;
  inputLabel: string;
  inputPlaceholder: string;
  inputHint: string;
  benefits: string[];
}

// ── Static integration configs ─────────────────────────────────

const INTEGRATIONS: IntegrationConfig[] = [
  {
    id: "google_analytics",
    name: "Google Analytics 4",
    icon: BarChart2,
    color: "text-orange-500",
    bg: "bg-orange-50",
    description:
      "Connect your GA4 property to enrich CRO recommendations with traffic and behavior data.",
    inputLabel: "Measurement ID",
    inputPlaceholder: "G-XXXXXXXXXX",
    inputHint:
      "Find this in GA4 → Admin → Data Streams → your stream → Measurement ID",
    benefits: [
      "Bounce rate context for each page",
      "Traffic source analysis",
      "Session duration insights",
    ],
  },
  {
    id: "hotjar",
    name: "Hotjar",
    icon: Flame,
    color: "text-red-500",
    bg: "bg-red-50",
    description:
      "Import heatmap and session recording data for deeper conversion insights.",
    inputLabel: "Site ID",
    inputPlaceholder: "1234567",
    inputHint:
      "Find your Site ID in Hotjar → Settings → Sites & Organizations",
    benefits: [
      "Heatmap analysis integration",
      "Rage click detection",
      "Scroll depth data",
    ],
  },
  {
    id: "clarity",
    name: "Microsoft Clarity",
    icon: MousePointer2,
    color: "text-blue-500",
    bg: "bg-blue-50",
    description:
      "Free heatmaps and session recordings to complement your CRO audits.",
    inputLabel: "Project ID",
    inputPlaceholder: "abc1234xyz",
    inputHint: "Find your Project ID in Clarity → Settings → your project",
    benefits: [
      "Free session recordings",
      "Click heatmaps",
      "Dead click detection",
    ],
  },
  {
    id: "search_console",
    name: "Google Search Console",
    icon: Search,
    color: "text-green-500",
    bg: "bg-green-50",
    description:
      "Understand which search keywords bring visitors who don't convert.",
    inputLabel: "Property URL",
    inputPlaceholder: "https://yoursite.com",
    inputHint:
      "Enter the exact property URL as listed in Google Search Console",
    benefits: [
      "Keyword performance data",
      "Click-through rate analysis",
      "Search intent matching",
    ],
  },
];

// ── Connect Dialog ─────────────────────────────────────────────

interface ConnectDialogProps {
  config: IntegrationConfig;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

function ConnectDialog({ config, open, onOpenChange }: ConnectDialogProps) {
  const [value, setValue] = useState("");
  const connectIntegration = useConnectIntegration();

  const handleSave = async () => {
    const trimmed = value.trim();
    if (!trimmed) return;

    try {
      await connectIntegration.mutateAsync({
        provider: config.id,
        trackingId: trimmed,
      });
      toast.success("Connected successfully");
      setValue("");
      onOpenChange(false);
    } catch {
      toast.error("Failed to connect. Please check your ID and try again.");
    }
  };

  const handleOpenChange = (nextOpen: boolean) => {
    if (!nextOpen) setValue("");
    onOpenChange(nextOpen);
  };

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Connect {config.name}</DialogTitle>
        </DialogHeader>

        <div className="space-y-3 py-2">
          <div className="space-y-1.5">
            <Label htmlFor="tracking-id">{config.inputLabel}</Label>
            <Input
              id="tracking-id"
              placeholder={config.inputPlaceholder}
              value={value}
              onChange={(e) => setValue(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter") handleSave();
              }}
              disabled={connectIntegration.isPending}
              autoFocus
            />
            <p className="text-xs text-muted-foreground">{config.inputHint}</p>
          </div>
        </div>

        <DialogFooter className="gap-2 sm:gap-0">
          <Button
            variant="outline"
            onClick={() => handleOpenChange(false)}
            disabled={connectIntegration.isPending}
          >
            Cancel
          </Button>
          <Button
            onClick={handleSave}
            disabled={!value.trim() || connectIntegration.isPending}
          >
            {connectIntegration.isPending ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Saving…
              </>
            ) : (
              "Save & Connect"
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

// ── Integration Card ───────────────────────────────────────────

interface IntegrationCardProps {
  config: IntegrationConfig;
  isConnected: boolean;
  onConnectRequest: () => void;
}

function IntegrationCard({
  config,
  isConnected,
  onConnectRequest,
}: IntegrationCardProps) {
  const Icon = config.icon;
  const disconnectIntegration = useDisconnectIntegration();

  const handleDisconnect = async () => {
    try {
      await disconnectIntegration.mutateAsync({ provider: config.id });
      toast.success(`${config.name} disconnected`);
    } catch {
      toast.error(`Failed to disconnect ${config.name}`);
    }
  };

  const handleSwitchChange = (checked: boolean) => {
    if (checked) {
      onConnectRequest();
    } else {
      handleDisconnect();
    }
  };

  return (
    <Card className="border-border/50 shadow-soft">
      <CardContent className="p-6">
        {/* Header row */}
        <div className="flex items-start justify-between">
          <div className="flex items-center gap-3">
            <div
              className={`flex h-12 w-12 items-center justify-center rounded-xl ${config.bg}`}
            >
              <Icon className={`h-6 w-6 ${config.color}`} />
            </div>
            <div>
              <h3 className="text-sm font-semibold text-foreground">
                {config.name}
              </h3>
              {isConnected ? (
                <Badge
                  variant="outline"
                  className="mt-1 border-green-200 bg-green-50 text-green-700 text-xs"
                >
                  <CheckCircle2 className="mr-1 h-3 w-3" />
                  Connected
                </Badge>
              ) : (
                <Badge
                  variant="outline"
                  className="mt-1 border-border text-muted-foreground text-xs"
                >
                  <Circle className="mr-1 h-3 w-3" />
                  Not connected
                </Badge>
              )}
            </div>
          </div>
          <Switch
            checked={isConnected}
            onCheckedChange={handleSwitchChange}
            disabled={disconnectIntegration.isPending}
            aria-label={`Toggle ${config.name} connection`}
          />
        </div>

        {/* Description */}
        <p className="mt-4 text-sm text-muted-foreground leading-relaxed">
          {config.description}
        </p>

        {/* Benefits */}
        <div className="mt-4">
          <p className="mb-2 text-xs font-medium uppercase tracking-wider text-muted-foreground">
            What you'll get
          </p>
          <ul className="space-y-1.5">
            {config.benefits.map((benefit) => (
              <li
                key={benefit}
                className="flex items-center gap-2 text-xs text-muted-foreground"
              >
                <span className="h-1 w-1 shrink-0 rounded-full bg-muted-foreground/50" />
                {benefit}
              </li>
            ))}
          </ul>
        </div>

        {/* Action button */}
        {isConnected ? (
          <Button
            variant="outline"
            size="sm"
            className="mt-4 w-full border-border/50 text-destructive hover:bg-destructive/5 hover:text-destructive"
            onClick={handleDisconnect}
            disabled={disconnectIntegration.isPending}
          >
            {disconnectIntegration.isPending ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Disconnecting…
              </>
            ) : (
              "Disconnect"
            )}
          </Button>
        ) : (
          <Button
            size="sm"
            className="mt-4 w-full"
            onClick={onConnectRequest}
          >
            Connect {config.name}
          </Button>
        )}
      </CardContent>
    </Card>
  );
}

// ── Loading skeletons ──────────────────────────────────────────

function IntegrationsSkeleton() {
  return (
    <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
      {Array.from({ length: 4 }).map((_, i) => (
        <Card key={i} className="border-border/50 shadow-soft">
          <CardContent className="p-6 space-y-4">
            <div className="flex items-start justify-between">
              <div className="flex items-center gap-3">
                <Skeleton className="h-12 w-12 rounded-xl" />
                <div className="space-y-2">
                  <Skeleton className="h-4 w-32" />
                  <Skeleton className="h-5 w-24 rounded-full" />
                </div>
              </div>
              <Skeleton className="h-5 w-9 rounded-full" />
            </div>
            <Skeleton className="h-4 w-full" />
            <Skeleton className="h-4 w-3/4" />
            <div className="space-y-1.5">
              <Skeleton className="h-3 w-20" />
              <Skeleton className="h-3 w-40" />
              <Skeleton className="h-3 w-36" />
              <Skeleton className="h-3 w-44" />
            </div>
            <Skeleton className="h-9 w-full rounded-md" />
          </CardContent>
        </Card>
      ))}
    </div>
  );
}

// ── Page ───────────────────────────────────────────────────────

const Integrations = () => {
  const [dialogProvider, setDialogProvider] =
    useState<IntegrationProvider | null>(null);

  const { data: integrations = [], isLoading } = useIntegrations();

  const connectedCount = integrations.filter((i) => i.is_active).length;
  const total = INTEGRATIONS.length;

  const activeDialog = INTEGRATIONS.find((c) => c.id === dialogProvider) ?? null;

  return (
    <PageTransition>
      <div className="space-y-6">
        <div className="flex items-start justify-between gap-4">
          <PageHeader
            title="Integrations"
            description="Connect your analytics tools for deeper CRO insights"
          />
          {!isLoading && (
            <div className="flex shrink-0 items-center gap-1.5 text-sm text-muted-foreground pt-1">
              <span className="font-medium text-foreground">
                {connectedCount}
              </span>{" "}
              of {total} integrations connected
            </div>
          )}
        </div>

        {isLoading ? (
          <IntegrationsSkeleton />
        ) : (
          <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
            {INTEGRATIONS.map((config) => {
              const connected = integrations.find(
                (i) => i.provider === config.id && i.is_active
              );
              return (
                <IntegrationCard
                  key={config.id}
                  config={config}
                  isConnected={!!connected}
                  onConnectRequest={() => setDialogProvider(config.id)}
                />
              );
            })}
          </div>
        )}

        {activeDialog && (
          <ConnectDialog
            config={activeDialog}
            open={dialogProvider !== null}
            onOpenChange={(open) => {
              if (!open) setDialogProvider(null);
            }}
          />
        )}
      </div>
    </PageTransition>
  );
};

export default Integrations;
